    @SuppressWarnings("unused")
    @QueryHandler
    public List<FundsTransfer> handle( FindAllFundsTransferQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindFundsTransfer,
 * but only if the id matches
 *
 * @param		entity	FundsTransfer
 */
	protected void emitFindFundsTransfer( FundsTransfer entity ) {
		LOGGER.info("handling emitFindFundsTransfer" );
		
	    queryUpdateEmitter.emit(FindFundsTransferQuery.class,
	                            query -> query.getFilter().getFundsTransferId().equals(entity.getFundsTransferId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllFundsTransfer
	 * 
	 * @param		entity	FundsTransfer
	 */
	protected void emitFindAllFundsTransfer( FundsTransfer entity ) {
		LOGGER.info("handling emitFindAllFundsTransfer" );
		
	    queryUpdateEmitter.emit(FindAllFundsTransferQuery.class,
	                            query -> true,
	                            entity);
	}

